```html
<!DOCTYPE html>
<html lang="zh">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>纯 CSS 3D 待办列表</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            min-height: 100vh;
            overflow: hidden;
            font-family: "PingFang SC", "Microsoft YaHei", system-ui, sans-serif;
            color: #fff;
        }

        .viewport {
            position: fixed;
            inset: 0;
            display: flex;
            align-items: center;
            justify-content: center;
            perspective: 1600px;
            background: radial-gradient(circle at 50% 60%, #1b2945 0%, #0a0e17 80%);
        }

        .carousel {
            position: relative;
            width: 0;
            height: 0;
            transform-style: preserve-3d;
        }

        /* 每张任务卡 */
        .todo-card {
            position: absolute;
            left: -120px;
            top: -80px;
            width: 240px;
            height: 160px;
            border-radius: 18px;
            padding: 18px 20px;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
            cursor: pointer;
            backface-visibility: hidden;
            -webkit-backface-visibility: hidden;
            box-shadow: 0 20px 35px rgba(0, 0, 0, 0.45);
            transition: transform 0.15s ease, box-shadow 0.2s ease;
            user-select: none;
            border: 1px solid rgba(255, 255, 255, 0.25);
        }

        .todo-card:hover {
            filter: brightness(1.15);
        }

        .todo-card .text {
            font-size: 16px;
            font-weight: 600;
            line-height: 1.4;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
            word-break: break-word;
            padding-right: 20px;
        }

        .todo-card .meta {
            font-size: 12px;
            opacity: 0.85;
            letter-spacing: 1px;
        }

        .del {
            position: absolute;
            top: 8px;
            right: 14px;
            background: none;
            border: none;
            color: #fff;
            font-size: 22px;
            line-height: 1;
            cursor: pointer;
            opacity: 0.55;
            padding: 4px;
            transition: opacity 0.2s;
        }

        .del:hover {
            opacity: 1;
        }

        /* 待办 */
        .pending {
            background: linear-gradient(145deg, rgba(255, 77, 77, 0.95), rgba(168, 30, 50, 0.95));
        }

        /* 已完成 */
        .done {
            background: linear-gradient(145deg, rgba(0, 200, 125, 0.95), rgba(10, 130, 85, 0.95));
        }

        /* 顶部提示 */
        .hint {
            position: fixed;
            top: 18px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(0, 0, 0, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.1);
