    render();
  }

  function toggleTask(index) {
    const task = tasks[index];
    if (!task.done) {
      task.done = true;
      addExp(EXP_PER_TASK);
    } else {
      task.done = false;
      exp = Math.max(0, exp - EXP_PER_TASK);
      render();
    }
  }

  function deleteTask(index) {
    tasks.splice(index, 1);
    render();
  }

  function addTask() {
    const text = input.value.trim();
    if (!text) return;
    tasks.push({ name: text, done: false });
    input.value = '';
    render();
  }

  function taskHtml(item, index) {
    return `
      <div class="task-item ${item.done ? 'done' : ''}">
        <span class="task-check" onclick="toggleTask(${index})">${item.done ? '✅' : '⬜'}</span>
        <span class="task-name"></span>
        <button class="task-del" onclick="deleteTask(${index})">🗑️</button>
      </div>
    `;
  }

  function render() {
    levelEl.textContent = level;
    expNowEl.textContent = exp;
    updateExpMaxLabel();

    const percent = Math.min(100, (exp / expMax) * 100);
    expFillEl.style.width = percent + '%';

    listEl.innerHTML = tasks.map((t, idx) => taskHtml(t, idx)).join('');

    // 用 textContent 赋值，避免输入内容变成 HTML
    const nameEls = listEl.querySelectorAll('.task-name');
    tasks.forEach((t, idx) => {
      nameEls[idx].textContent = t.name;
    });

    doneCountEl.textContent = tasks.filter(t => t.done).length;
    totalCountEl.textContent = tasks.length;
  }

  function resetAll() {
    if (confirm('确定重置整个冒险吗？所有任务会清空。')) {
      tasks = [];
      level = 1;
      exp = 0;
      expMax = 50;
      render();
    }
  }

  input.addEventListener('keydown', e => {
    if (e.key === 'Enter') addTask();
  });

  render();
</script>
</body>
</html>
